+
+export function useColumnConfigs<D extends DataRecord = DataRecord>({
+  defaultAlignPN,
+  defaultColorPN,
+  emitCrossFilters,
+  getValueRange,
+  isActiveFilterValue,
+  isRawRecords,
+  showCellBars,
+  sortDesc,
+  totals,
+  columnColorFormatters,
+  allowRearrangeColumns,
+  allowRenderHtml,
+  basicColorColumnFormatters,
+  basicColorFormatters,
+  comparisonLabels,
+  getSharedStyle,
+  groupHeaderColumns,
+  handleContextMenu,
+  handleToggleFilter,
+  isUsingTimeComparison,
+  SortIcon,
