+          let color;
+          let arrow = '';
+          const originKey = column.key.substring(column.label.length).trim();
+          if (!hasColumnColorFormatters && hasBasicColorFormatters) {
+            backgroundColor =
+              basicColorFormatters[row.index][originKey]?.backgroundColor;
+            arrow =
+              column.label === comparisonLabels[0]
+                ? basicColorFormatters[row.index][originKey]?.mainArrow
+                : '';
+          }
+
+          if (hasColumnColorFormatters) {
+            const applyFormatter = (
+              formatter: ColorFormatters[number],
+              valueToFormat: any,
+            ) => {
+              const hasValue =
+                valueToFormat !== undefined && valueToFormat !== null;
+              if (!hasValue) return;
+
+              const formatterResult =
+                formatter.getColorFromValue(valueToFormat);
+              if (!formatterResult) return;
+
+              if (formatter.toTextColor) {
+                color = formatterResult.slice(0, -2);
+              } else {
+                backgroundColor = formatterResult;
+              }
+            };
+            columnColorFormatters
+              .filter(formatter => formatter.column === column.key)
+              .forEach(formatter => applyFormatter(formatter, value));
+
+            columnColorFormatters
+              .filter(formatter => formatter.toAllRow)
+              .forEach(formatter =>
+                applyFormatter(formatter, row.original[formatter.column]),
+              );
+          }
+
+          if (
+            basicColorColumnFormatters &&
+            basicColorColumnFormatters?.length > 0
+          ) {
+            backgroundColor =
+              basicColorColumnFormatters[row.index][column.key]
+                ?.backgroundColor || backgroundColor;
+            arrow =
+              column.label === comparisonLabels[0]
+                ? basicColorColumnFormatters[row.index][column.key]?.mainArrow
+                : '';
+          }
+          const StyledCell = styled.td`
+            color: ${color ? `${color}FF` : theme.colorText};
+            text-align: ${sharedStyle.textAlign};
+            white-space: ${value instanceof Date ? 'nowrap' : undefined};
+            position: relative;
+            background: ${backgroundColor || undefined};
+            padding-left: ${column.isChildColumn
+              ? `${theme.sizeUnit * 5}px`
+              : `${theme.sizeUnit}px`};
+          `;
+
+          const cellBarStyles = css`
+            position: absolute;
+            height: 100%;
+            display: block;
+            top: 0;
+            ${valueRange &&
+            `
+                width: ${`${cellWidth({
+                  value: value as number,
+                  valueRange,
+                  alignPositiveNegative,
+                })}%`};
+                left: ${`${cellOffset({
+                  value: value as number,
+                  valueRange,
+                  alignPositiveNegative,
+                })}%`};
+                background-color: ${cellBackground({
+                  value: value as number,
+                  colorPositiveNegative,
+                  theme,
+                })};
+              `}
+          `;
+
+          let arrowStyles = css`
+            color: ${basicColorFormatters &&
+            basicColorFormatters[row.index][originKey]?.arrowColor ===
+              ColorSchemeEnum.Green
+              ? theme.colorSuccess
+              : theme.colorError};
+            margin-right: ${theme.sizeUnit}px;
+          `;
+
+          if (
+            basicColorColumnFormatters &&
+            basicColorColumnFormatters?.length > 0
+          ) {
+            arrowStyles = css`
+              color: ${basicColorColumnFormatters[row.index][column.key]
+                ?.arrowColor === ColorSchemeEnum.Green
+                ? theme.colorSuccess
+                : theme.colorError};
+              margin-right: ${theme.sizeUnit}px;
+            `;
+          }
+
+          const cellProps = {
+            'aria-labelledby': `header-${column.key}`,
+            role: 'cell',
+            title: typeof value === 'number' ? String(value) : undefined,
+            onClick:
+              emitCrossFilters && !valueRange && !isMetric
+                ? () => {
+                    if (!getSelectedText()) handleToggleFilter(key, value);
+                  }
+                : undefined,
+            onContextMenu: (e: MouseEvent) => {
+              if (handleContextMenu) {
+                e.preventDefault();
+                e.stopPropagation();
+                handleContextMenu(
+                  row.original,
+                  { key, value, isMetric },
+                  e.nativeEvent.clientX,
+                  e.nativeEvent.clientY,
+                );
+              }
+            },
+            className: [
+              className,
+              value == null ||
+              (value instanceof DateWithFormatter && value.input == null)
+                ? 'dt-is-null'
+                : '',
+              isActiveFilterValue(key, value) ? ' dt-is-active-filter' : '',
+            ].join(' '),
+            tabIndex: 0,
+          };
+
+          if (html) {
+            if (truncateLongCells) {
+              return (
+                <StyledCell {...cellProps}>
+                  <div
+                    className="dt-truncate-cell"
+                    style={columnWidth ? { width: columnWidth } : undefined}
+                    dangerouslySetInnerHTML={html}
+                  />
+                </StyledCell>
+              );
+            }
+
+            return <StyledCell {...cellProps} dangerouslySetInnerHTML={html} />;
+          }
+
+          return (
+            <StyledCell {...cellProps}>
+              {valueRange && (
+                <div
+                  /* The following classes are added to support custom CSS styling */
+                  className={cx(
+                    'cell-bar',
+                    typeof value === 'number' && value < 0
+                      ? 'negative'
+                      : 'positive',
+                  )}
+                  css={cellBarStyles}
+                  role="presentation"
+                />
+              )}
+              {truncateLongCells ? (
+                <div
+                  className="dt-truncate-cell"
+                  style={columnWidth ? { width: columnWidth } : undefined}
+                >
+                  {arrow && <span css={arrowStyles}>{arrow}</span>}
+                  {text}
+                </div>
+              ) : (
+                <>
+                  {arrow && <span css={arrowStyles}>{arrow}</span>}
+                  {text}
+                </>
+              )}
+            </StyledCell>
+          );
+        },
+        Header: ({ column: col, onClick, style, onDragStart, onDrop }) => (
+          <th
+            id={`header-${column.originalLabel}`}
+            title={t('Shift + Click to sort by multiple columns')}
+            className={[className, col.isSorted ? 'is-sorted' : ''].join(' ')}
+            style={{
+              ...sharedStyle,
+              ...style,
+            }}
+            onKeyDown={(e: ReactKeyboardEvent<HTMLElement>) => {
+              if (Object.values(ACTION_KEYS).includes(e.key))
+                col.toggleSortBy();
+            }}
+            role="columnheader button"
+            onClick={onClick}
+            data-column-name={col.id}
+            {...(allowRearrangeColumns && {
+              draggable: 'true',
+              onDragStart,
+              onDragOver: e => e.preventDefault(),
+              onDragEnter: e => e.preventDefault(),
+              onDrop,
+            })}
+            tabIndex={0}
+          >
+            {config.columnWidth ? (
+              <div
+                style={{
+                  width: columnWidth,
+                  height: 0.01,
+                }}
+              />
+            ) : null}
+            <div
+              data-column-name={col.id}
+              css={{
+                display: 'inline-flex',
+                alignItems: 'flex-end',
+              }}
+            >
+              <span data-column-name={col.id}>{displayLabel}</span>
+              <SortIcon column={col} />
+            </div>
+          </th>
+        ),
+
+        Footer: totals ? (
+          i === 0 ? (
+            <th key={`footer-summary-${i}`}>
+              <div
+                css={css`
+                  display: flex;
+                  align-items: center;
+                  & svg {
+                    margin-left: ${theme.sizeUnit}px;
+                    color: ${theme.colorBorder} !important;
+                  }
+                `}
+              >
+                {t('Summary')}
+                <Tooltip
+                  overlay={t(
+                    'Show total aggregations of selected metrics. Note that row limit does not apply to the result.',
+                  )}
+                >
+                  <InfoCircleOutlined />
+                </Tooltip>
+              </div>
+            </th>
+          ) : (
+            <td key={`footer-total-${i}`} style={sharedStyle}>
+              <strong>{formatColumnValue(column, totals[key])[1]}</strong>
+            </td>
+          )
+        ) : undefined,
+        sortDescFirst: sortDesc,
+        sortType: getSortTypeByDataType(dataType),
+      };
+    },
+    [
+      defaultAlignPN,
+      defaultColorPN,
+      emitCrossFilters,
+      getValueRange,
+      isActiveFilterValue,
+      isRawRecords,
+      showCellBars,
+      sortDesc,
+      totals,
+      columnColorFormatters,
+      theme,
+      allowRearrangeColumns,
+      allowRenderHtml,
+      basicColorColumnFormatters,
+      basicColorFormatters,
+      comparisonLabels,
+      getSharedStyle,
+      groupHeaderColumns,
+      handleContextMenu,
+      handleToggleFilter,
+      isUsingTimeComparison,
+      SortIcon,
+    ],
+  );
+
+  return getColumnConfigs;
+}

