+import { useState, useEffect } from 'react';
+import { ColumnWithLooseAccessor } from 'react-table';
+import { isEqual } from 'lodash';
+import { SearchOption } from '../../../types';
+
+/**
+ * Derives search options from table columns. Filters for alphanumeric columns
+ * that can be searched and memoizes the result to avoid unnecessary updates.
+ */
+export function useSearchOptions(
+  columns: (ColumnWithLooseAccessor & {
+    columnKey: string;
+    sortType?: string;
+  })[],
+): SearchOption[] {
+  const [searchOptions, setSearchOptions] = useState<SearchOption[]>([]);
+
+  useEffect(() => {
+    const options = columns
+      .filter(col => col?.sortType === 'alphanumeric')
+      .map(column => ({
+        value: column.columnKey,
+        label: column.columnKey,
+      }));
+
+    setSearchOptions(prev => (isEqual(options, prev) ? prev : options));
+  }, [columns]);
+
+  return searchOptions;
+}

