+  const tr = document.createElement('tr');
+  for (let i = 0; i < numCols; i += 1) {
+    const th = document.createElement('th');
+    tr.appendChild(th);
+  }
+  thead.appendChild(tr);
+  table.appendChild(thead);
+  document.body.appendChild(table);
+  return table;
+};
+
+afterEach(() => {
+  document.body.innerHTML = '';
+});
