+import { Button, Input } from '@superset-ui/core/components';
+import { Icons } from '@superset-ui/core/components/Icons';
+import { FoldersToolbar, FoldersSearch, FoldersActions } from '../styles';
+
+interface FoldersToolbarComponentProps {
+  onSearch: (e: React.ChangeEvent<HTMLInputElement>) => void;
+  onAddFolder: () => void;
+  onSelectAll: () => void;
+  onResetToDefault: () => void;
+  allVisibleSelected: boolean;
+}
+
+function FoldersToolbarComponentInner({
+  onSearch,
+  onAddFolder,
+  onSelectAll,
+  onResetToDefault,
+  allVisibleSelected,
+}: FoldersToolbarComponentProps) {
+  return (
+    <FoldersToolbar>
+      <FoldersSearch>
+        <Input
+          placeholder={t('Search all metrics & columns')}
+          onChange={onSearch}
+          allowClear
+          prefix={<Icons.SearchOutlined />}
+        />
+      </FoldersSearch>
+      <FoldersActions>
+        <Button
+          buttonStyle="link"
+          onClick={onAddFolder}
+          icon={<Icons.PlusOutlined />}
+        >
+          {t('Add folder')}
+        </Button>
+        <Button
+          buttonStyle="link"
+          onClick={onSelectAll}
+          icon={<Icons.CheckOutlined />}
