+function getMaxDepth(previousItem: FlattenedTreeItem | undefined): number {
+  if (previousItem) {
+    if (previousItem.type === FoldersEditorItemType.Folder) {
+      return Math.min(previousItem.depth + 1, MAX_DEPTH);
+    }
+    return previousItem.depth;
+  }
+  return 0;
