+    endpointType,
+    force,
+    allowDomainSharding,
+    method,
+    requestParams: requestParams.dashboard_id
+      ? { dashboard_id: String(requestParams.dashboard_id) }
+      : {},
+  });
+  const querySettings: QuerySettings = {
+    ...requestParams,
+    url: url ?? undefined,
+    postPayload: { form_data: formData },
+    parseMethod,
+  };
