+const isAceAnnotation = (ann: unknown): ann is AceAnnotation =>
+  typeof ann === 'object' &&
+  ann !== null &&
+  'row' in ann &&
+  'column' in ann &&
+  'text' in ann &&
+  'type' in ann;
