+const toAceKeyword = (keyword: EditorKeyword): AceCompleterKeyword => ({
+  name: keyword.name,
+  value: keyword.value ?? keyword.name,
+  score: keyword.score ?? 0,
+  meta: keyword.meta ?? '',
