+  xAxis: axisSchema,
+  yAxis: axisSchema,
+  tooltip: tooltipSchema,
+  dataZoom: dataZoomSchema,
+  toolbox: toolboxSchema,
+  visualMap: visualMapSchema,
+  series: seriesSchema,
+  graphic: graphicElementSchema,
