+    const scopeConfig = customizationScopes
+      .map(({ customizationId, chartsInScope, tabsInScope }) => {
+        const existing = filters[customizationId];
+        if (!existing) return null;
+        return {
+          ...existing,
+          chartsInScope,
+          tabsInScope,
+        };
+      })
