+  | NativeFiltersFormItem
+  | NativeFilterDivider
+  | Filter
+  | Divider {
+  return (
+    'type' in formInputs &&
+    (formInputs.type === NativeFilterType.NativeFilter ||
+      formInputs.type === NativeFilterType.Divider)
+  );
+}
