+    const result = mergeReplaceArrays(baseOptions, overrides);
+
+    // Arrays are replaced entirely, not merged by index
+    expect(result.series).toEqual([{ name: 'New Series', type: 'pie' }]);
+    expect(result.series).toHaveLength(1);
