+        right: '5%', // preserved (undefined values are ignored by lodash merge)
+        top: '10%', // preserved
+        bottom: '20%', // added
+      },
+      tooltip: {
+        show: true, // preserved
+        backgroundColor: null, // overridden with null
+        borderColor: '#ccc', // added
+      },
